examples.template:
VStack(alignment: .leading, spacing: theme.spacing.space4) {
    MonarchFlowLayout(spacing: theme.spacing.space2) {
        ForEach(filters) { filter in
            MonarchTag(
                filter.name + ": " + filter.value,
                removeLabel: "Remove " + filter.name + " filter",
                onRemove: { filters.removeAll { $0.id == filter.id } }
            )
        }
        if !filters.isEmpty {
            Button("Clear all") { filters = [] }
                .buttonStyle(.plain)
                .monarchTextStyle(.label)
                .foregroundStyle(theme.colors.textLink)
                .monarchMinimumHitTarget()
        }
    }
}
.padding(theme.spacing.space4)
.frame(minHeight: theme.spacing.space24)

examples.setupTemplate:
@Environment(\.monarchTheme) private var theme

struct Filter: Identifiable {
    let name: String
    let value: String
    var id: String { name }
}

@State private var filters = [
    Filter(name: {{filters.0.name}}, value: {{filters.0.value}}),
    Filter(name: {{filters.1.name}}, value: {{filters.1.value}}),
    Filter(name: {{filters.2.name}}, value: {{filters.2.value}}),
]

